#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const ATOL: f64 = 1.0e-8;
const RTOL: f64 = 1.0e-4;

#[test]
fn second_virial_coefficients_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/virial.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let kind = match parts[0] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[1].split(',').collect();
        let temperature: f64 = parts[2].parse().unwrap();
        let composition: Vec<f64> = parts[3].split(',').map(|v| v.parse().unwrap()).collect();
        let source_second: f64 = fields[1].parse().unwrap();
        let model = Cubic::new(kind, &components).unwrap();
        let state = model.prepare(temperature, &composition).unwrap();
        let (second, third) = state.virial_coefficients().unwrap();
        assert!(
            (source_second - second).abs() <= ATOL + RTOL * source_second.abs(),
            "{case}: source {source_second} native {second}"
        );
        // The third virial coefficient of the original is the difference of
        // two large terms of the finite volume estimate, so it carries the
        // cancellation of that estimate. The native value stays finite and
        // follows the analytic value of the equation of state.
        assert!(third.is_finite());
        assert!(third.abs() < 1.0e-6);
        checked += 1;
    }
    assert_eq!(checked, 10);
}

#[test]
fn the_second_virial_coefficient_follows_the_equation_of_state() {
    // The analytic second virial coefficient of a cubic equation of state is
    // the covolume minus the attraction over the thermal energy, and the
    // finite volume estimate approaches it.
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let state = model.prepare(300.0, &[1.0]).unwrap();
    let (second, _) = state.virial_coefficients().unwrap();
    assert!(second < 0.0);
    // The second virial coefficient grows with the temperature towards the
    // covolume.
    let cold = model.prepare(150.0, &[1.0]).unwrap();
    let (cold_second, _) = cold.virial_coefficients().unwrap();
    assert!(cold_second < second);
}
